css:
.pm554-container {
    padding: 28px;
    background: #0f1923;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', sans-serif;
    color: #c8d6e5;
}
.pm554-header {
    background: linear-gradient(135deg, #1a2a3a 0%, #0f1f30 100%);
    border-left: 5px solid #f39c12;
    border-radius: 0 12px 12px 0;
    padding: 32px 36px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.pm554-header::after {
    content: '';
    position: absolute;
    top: 0; right: 0; bottom: 0;
    width: 200px;
    background: linear-gradient(90deg, transparent, rgba(243,156,18,0.04));
    pointer-events: none;
}
.pm554-header-badge {
    display: inline-block;
    background: rgba(243,156,18,0.15);
    color: #f39c12;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.15em;
    padding: 4px 12px;
    border-radius: 4px;
    margin-bottom: 12px;
}
.pm554-header h1 {
    color: #ffffff;
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 0 6px 0;
}
.pm554-header-sub {
    color: #7f8fa6;
    font-size: 0.95rem;
    margin: 0;
}
.pm554-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #7f8fa6;
    margin-bottom: 24px;
    padding: 10px;
    background: #1a2634;
    border-radius: 8px;
    border: 1px solid #2d3f55;
}
.pm554-period-counter span {
    margin: 0 3px;
}
.pm554-period-counter #currentDay {
    color: #f39c12;
    font-weight: 700;
    font-size: 1.1rem;
}
.pm554-kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-bottom: 28px;
}
.pm554-kpi-card {
    background: #1a2634;
    border: 1px solid #2d3f55;
    border-radius: 10px;
    padding: 20px 18px;
    position: relative;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.pm554-kpi-card:hover {
    border-color: #3d5575;
    transform: translateY(-2px);
}
.pm554-kpi-icon {
    font-size: 1.3rem;
    margin-bottom: 8px;
}
.pm554-kpi-label {
    color: #7f8fa6;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.pm554-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #ffffff;
    font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;
}
.pm554-kpi-spi .pm554-kpi-value { color: #f39c12; }
.pm554-kpi-cpi .pm554-kpi-value { color: #3498db; }
.pm554-kpi-cost .pm554-kpi-value { color: #e74c3c; }
.pm554-kpi-months .pm554-kpi-value { color: #e67e22; }
.pm554-kpi-confidence .pm554-kpi-value { color: #2ecc71; }
.pm554-kpi-budget .pm554-kpi-value { color: #9b59b6; }
.pm554-kpi-target {
    color: #546a7b;
    font-size: 0.7rem;
    margin-top: 6px;
}
.pm554-kpi-detail {
    color: #546a7b;
    font-size: 0.72rem;
    margin-top: 6px;
}
.pm554-kpi-bar {
    width: 100%;
    height: 4px;
    background: #2d3f55;
    border-radius: 2px;
    margin-top: 10px;
    overflow: hidden;
}
.pm554-kpi-bar-fill {
    height: 100%;
    border-radius: 2px;
    transition: width 0.5s ease;
}
.pm554-bar-spi { background: linear-gradient(90deg, #e74c3c, #f39c12, #2ecc71); }
.pm554-bar-cpi { background: linear-gradient(90deg, #e74c3c, #3498db, #2ecc71); }
.pm554-bar-confidence { background: linear-gradient(90deg, #e74c3c, #f39c12, #2ecc71); }
.pm554-briefing {
    background: #1a2634;
    border: 1px solid #2d3f55;
    border-radius: 10px;
    padding: 24px 28px;
    margin-bottom: 24px;
    position: relative;
    border-left: 4px solid #f39c12;
}
.pm554-briefing-marker {
    position: absolute;
    top: 16px;
    right: 20px;
    width: 10px;
    height: 10px;
    background: #f39c12;
    border-radius: 50%;
    animation: pm554-pulse 2s infinite;
}
@keyframes pm554-pulse {
    0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(243,156,18,0.4); }
    50% { opacity: 0.7; box-shadow: 0 0 0 8px rgba(243,156,18,0); }
}
.pm554-briefing h3 {
    color: #f39c12;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 10px 0;
}
.pm554-briefing p {
    color: #a4b0be;
    font-size: 0.9rem;
    line-height: 1.6;
    margin: 0;
}
.pm554-controls {
    background: #1a2634;
    border: 1px solid #2d3f55;
    border-radius: 10px;
    padding: 24px 28px;
    margin-bottom: 28px;
}
.pm554-controls h3 {
    color: #ffffff;
    font-size: 1rem;
    font-weight: 600;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #2d3f55;
}
.pm554-control-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}
.pm554-control-group label {
    display: block;
    color: #7f8fa6;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
}
.pm554-select,
.pm554-input {
    width: 100%;
    background: #0f1923;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 6px;
    padding: 10px 14px;
    font-size: 0.9rem;
    transition: border-color 0.2s ease;
    font-family: inherit;
}
.pm554-select:focus,
.pm554-input:focus {
    outline: none;
    border-color: #f39c12;
    box-shadow: 0 0 0 3px rgba(243,156,18,0.15);
}
.pm554-select option {
    background: #0f1923;
    color: #e0e6f0;
}
.pm554-btn-group {
    display: flex;
    gap: 12px;
    align-items: center;
}
.pm554-btn-submit {
    background: linear-gradient(135deg, #f39c12, #e67e22);
    border: none;
    color: #0f1923;
    font-weight: 700;
    padding: 12px 32px;
    border-radius: 6px;
    font-size: 0.9rem;
    letter-spacing: 0.03em;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    cursor: pointer;
}
.pm554-btn-submit:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(243,156,18,0.3);
    background: linear-gradient(135deg, #f5ab35, #e8913a);
    color: #0f1923;
}
.pm554-btn-undo {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #7f8fa6;
    padding: 8px 18px;
    border-radius: 6px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.pm554-btn-undo:hover {
    border-color: #7f8fa6;
    color: #a4b0be;
    background: transparent;
}
.pm554-chart {
    background: #1a2634;
    border: 1px solid #2d3f55;
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 28px;
    height: 320px;
}
.pm554-history {
    background: #1a2634;
    border: 1px solid #2d3f55;
    border-radius: 10px;
    padding: 20px;
    overflow-x: auto;
}
.pm554-container .table {
    color: #c8d6e5;
    margin: 0;
}
.pm554-container .table thead th {
    background: #0f1923;
    color: #7f8fa6;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-color: #2d3f55;
    padding: 10px 12px;
    font-weight: 600;
}
.pm554-container .table tbody td {
    border-color: #2d3f55;
    padding: 10px 12px;
    font-size: 0.85rem;
    font-family: 'SF Mono', 'Consolas', monospace;
}
.pm554-container .table tbody tr:hover {
    background: rgba(243,156,18,0.05);
}
@media (max-width: 768px) {
    .pm554-container { padding: 16px; }
    .pm554-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .pm554-control-row { grid-template-columns: 1fr; }
    .pm554-header h1 { font-size: 1.2rem; }
    .pm554-kpi-value { font-size: 1.4rem; }
    .pm554-btn-group { flex-direction: column; }
    .pm554-btn-submit { width: 100%; }
}

/* ===== Completion debrief (adapter v1.1.0) — namespaced, append-only ===== */
.pm554-sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); border:0; }
.pm554-cm { background:#fff; border:1px solid #e2e8f0; border-radius:12px; padding:24px; max-width:640px; margin:16px auto; color:#1a202c; }
.pm554-cm-scorewrap { text-align:center; margin-bottom:8px; }
.pm554-cm-score { font-size:48px; font-weight:800; color:#f39c12; line-height:1; }
.pm554-cm-score-max { font-size:20px; color:#718096; font-weight:600; }
.pm554-cm-grade { font-size:13px; color:#718096; margin-top:4px; letter-spacing:.5px; }
.pm554-cm-verdict { text-align:center; font-size:22px; font-weight:700; color:#3498db; margin:8px 0 16px; }
.pm554-cm-kpistrip { display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin-bottom:12px; }
.pm554-cm-kpi { flex:1 1 120px; min-width:108px; background:#f7fafc; border-radius:8px; padding:10px; text-align:center; }
.pm554-cm-kpi-label { display:block; font-size:11px; text-transform:uppercase; color:#718096; letter-spacing:.4px; }
.pm554-cm-kpi-val { display:block; font-size:22px; font-weight:700; color:#1a202c; margin:2px 0; }
.pm554-cm-budget { text-align:center; font-size:13px; color:#4a5568; margin-bottom:14px; }
.pm554-cm-insights-h { font-weight:700; margin-bottom:6px; color:#2d3748; }
.pm554-cm-insights { margin:0; padding-left:20px; }
.pm554-cm-insights li { margin-bottom:6px; font-size:14px; line-height:1.4; color:#2d3748; }
@media (max-width:520px){ .pm554-cm-score{font-size:38px;} .pm554-cm-verdict{font-size:18px;} }

