            if (briefTitle) briefTitle.innerHTML = t(titles[idx]);

            var briefText = document.getElementById('briefingText');
            if (briefText) briefText.innerHTML = t(descs[idx]);

            var primaryLabelEl = document.getElementById('primaryLabel');
            if (primaryLabelEl) primaryLabelEl.innerHTML = t(primaryLabels[idx]);

            var secondaryLabelEl = document.getElementById('secondaryLabel');
            if (secondaryLabelEl) secondaryLabelEl.innerHTML = t(secondaryLabels[idx]);

            var options = this.ROUND_OPTIONS[idx];
            var select = document.getElementById('primarySelect');
            if (select) {
                select.innerHTML = '';
                options.forEach(function(opt) {
                    var o = document.createElement('option');
                    o.value = opt.value;
                    o.textContent = t(opt.i18nKey);
                    select.appendChild(o);
                });
            }

            var constraints = this.ROUND_CONSTRAINTS[idx];
            var input = document.getElementById('secondaryInput');
            if (input) {
                input.min = constraints.min;
                input.max = constraints.max;
                input.value = constraints.defaultVal;
            }

            var spiBar = document.getElementById('spiBar');
            if (spiBar && state.domainState) {
                spiBar.style.width = Math.min(100, Math.round(state.domainState.spi * 100)) + '%';
            }
            var cpiBar = document.getElementById('cpiBar');
            if (cpiBar && state.domainState) {
                cpiBar.style.width = Math.min(100, Math.round(state.domainState.cpi * 100)) + '%';
            }
            var confBar = document.getElementById('confidenceBar');
            if (confBar && state.domainState) {
                confBar.style.width = Math.round(state.domainState.stakeholderConfidence) + '%';
            }
        }

        validateDecisions(decisions) {
            var select = document.getElementById('primarySelect');
            if (select) decisions.primary = select.value;

            var input = document.getElementById('secondaryInput');
            if (input) decisions.secondary = parseFloat(input.value);

            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, 3);
            var c = this.ROUND_CONSTRAINTS[idx];

            if (decisions.secondary === null || decisions.secondary === undefined || isNaN(decisions.secondary) || decisions.secondary < c.min || decisions.secondary > c.max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_invalid_input'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var result = {};

            // Idempotency: snapshot pre-scoring cumulative state; restore on re-entry.
            if (!ds._baselines) ds._baselines = {};
            if (ds._baselines[period]) {
                var _b = ds._baselines[period];
                ds.spi = _b.spi; ds.cpi = _b.cpi; ds.projectedCost = _b.projectedCost;
                ds.projectedMonths = _b.projectedMonths; ds.stakeholderConfidence = _b.stakeholderConfidence;
                ds.rootCauseAccuracy = _b.rootCauseAccuracy; ds.recoveryBudgetUsed = _b.recoveryBudgetUsed;
                ds.spiHistory = _b.spiHistory.slice(); ds.cpiHistory = _b.cpiHistory.slice();
            } else {
                ds._baselines[period] = {
                    spi: ds.spi, cpi: ds.cpi, projectedCost: ds.projectedCost,
                    projectedMonths: ds.projectedMonths, stakeholderConfidence: ds.stakeholderConfidence,
                    rootCauseAccuracy: ds.rootCauseAccuracy, recoveryBudgetUsed: ds.recoveryBudgetUsed,
                    spiHistory: ds.spiHistory.slice(), cpiHistory: ds.cpiHistory.slice()
                };
            }

            if (period === 1) {
                var accuracy = 0;
                if (d.primary === 'geology') {
                    accuracy = Math.min(95, 50 + d.secondary * 3);
                    ds.spi += 0.02;
                    ds.cpi += 0.01;
                } else if (d.primary === 'estimation') {
                    accuracy = Math.min(80, 40 + d.secondary * 2);
                    ds.spi += 0.01;
                    ds.cpi += 0.02;
                } else if (d.primary === 'weather') {
                    accuracy = Math.min(50, 20 + d.secondary * 1.5);
                    ds.spi += 0.01;
                    ds.cpi += 0.005;
                } else if (d.primary === 'labor') {
                    accuracy = Math.min(60, 25 + d.secondary * 2);
                    ds.spi += 0.005;
                    ds.cpi += 0.01;
                }
                ds.rootCauseAccuracy = Math.round(accuracy);
                ds.recoveryBudgetUsed += d.secondary;
                ds.projectedCost += d.secondary;
                result = {
                    period: period,
                    strategy: d.primary,
                    budgetAllocated: d.secondary,
                    rootCauseAccuracy: ds.rootCauseAccuracy,
                    spi: Math.round(ds.spi * 1000) / 1000,
                    cpi: Math.round(ds.cpi * 1000) / 1000,
                    projectedCost: Math.round(ds.projectedCost)
                };
            } else if (period === 2) {
                var rcBonus = ds.rootCauseAccuracy / 100;
                if (d.primary === 'fast-track') {
                    ds.spi += (0.06 + d.secondary * 0.0003) * (0.5 + rcBonus * 0.5);
                    ds.cpi -= 0.02;
                    ds.projectedMonths -= Math.round(3 * rcBonus + d.secondary * 0.01);
                    ds.projectedCost += Math.round(d.secondary * 0.8);
                } else if (d.primary === 'crash') {
                    ds.spi += (0.10 + d.secondary * 0.0004) * (0.5 + rcBonus * 0.5);
                    ds.cpi -= 0.05;
                    ds.projectedMonths -= Math.round(5 * rcBonus + d.secondary * 0.015);
                    ds.projectedCost += Math.round(d.secondary * 1.5);
                } else if (d.primary === 'scope-reduction') {
                    ds.spi += 0.04 * (0.5 + rcBonus * 0.5);
                    ds.cpi += 0.03 + d.secondary * 0.0002;
                    ds.projectedMonths -= Math.round(2 * rcBonus + d.secondary * 0.005);
                    ds.projectedCost -= Math.round(40 + d.secondary * 0.3);
                } else if (d.primary === 'hybrid') {
                    ds.spi += (0.05 + d.secondary * 0.0002) * (0.5 + rcBonus * 0.5);
                    ds.cpi += 0.01;
                    ds.projectedMonths -= Math.round(3 * rcBonus + d.secondary * 0.008);
                    ds.projectedCost += Math.round(d.secondary * 0.5);
                }
                ds.recoveryBudgetUsed += d.secondary;
                result = {
                    period: period,
                    strategy: d.primary,
                    budgetAllocated: d.secondary,
                    spi: Math.round(ds.spi * 1000) / 1000,
                    cpi: Math.round(ds.cpi * 1000) / 1000,
                    projectedCost: Math.round(ds.projectedCost),
                    projectedMonths: ds.projectedMonths
                };
            } else if (period === 3) {
                if (d.primary === 'full-disclosure') {
                    ds.stakeholderConfidence += 25 + d.secondary * 0.15;
                    ds.spi += 0.01;
                } else if (d.primary === 'partial') {
                    ds.stakeholderConfidence += 15 + d.secondary * 0.1;
                    ds.spi += 0.005;
                } else if (d.primary === 'minimal') {
                    ds.stakeholderConfidence += 5;
                    ds.cpi += 0.01;
                } else if (d.primary === 'optimistic') {
                    ds.stakeholderConfidence += 20;
                    if (ds.projectedMonths > 52) {
                        ds.stakeholderConfidence -= 15;
                    }
                }
                ds.stakeholderConfidence = Math.min(100, Math.max(0, Math.round(ds.stakeholderConfidence)));
                result = {
                    period: period,
                    strategy: d.primary,
                    budgetAllocated: d.secondary,
                    spi: Math.round(ds.spi * 1000) / 1000,
                    cpi: Math.round(ds.cpi * 1000) / 1000,
                    projectedCost: Math.round(ds.projectedCost),
                    stakeholderConfidence: ds.stakeholderConfidence
                };
            } else if (period === 4) {
                var buffer = d.secondary;
                if (d.primary === 'schedule') {
                    ds.projectedMonths -= buffer;
                    ds.projectedCost += buffer * 12;
                    ds.spi += 0.03 + buffer * 0.005;
                    ds.cpi -= buffer * 0.003;
                } else if (d.primary === 'cost') {
                    ds.projectedCost -= 30 + buffer * 5;
                    ds.projectedMonths += Math.round(buffer * 0.3);
                    ds.cpi += 0.04;
                    ds.spi -= 0.01;
                } else if (d.primary === 'quality') {
                    ds.stakeholderConfidence = Math.min(100, ds.stakeholderConfidence + 15);
                    ds.projectedCost += 20 + buffer * 3;
                    ds.spi += 0.01;
                    ds.cpi -= 0.01;
                } else if (d.primary === 'balanced') {
                    ds.projectedMonths -= Math.round(buffer * 0.5);
                    ds.projectedCost -= 15;
                    ds.spi += 0.02;
                    ds.cpi += 0.02;
                    ds.stakeholderConfidence = Math.min(100, ds.stakeholderConfidence + 10);
                }
                ds.recoveryBudgetUsed += buffer * 8;
                result = {
                    period: period,
                    strategy: d.primary,
                    budgetAllocated: d.secondary,
                    spi: Math.round(ds.spi * 1000) / 1000,
                    cpi: Math.round(ds.cpi * 1000) / 1000,
                    projectedCost: Math.round(ds.projectedCost),
                    projectedMonths: ds.projectedMonths,
                    stakeholderConfidence: ds.stakeholderConfidence
                };
            }

            ds.spi = Math.round(ds.spi * 1000) / 1000;
            ds.cpi = Math.round(ds.cpi * 1000) / 1000;
            ds.projectedMonths = Math.max(36, ds.projectedMonths);
            ds.projectedCost = Math.max(800, ds.projectedCost);

            // Per-period history by index (idempotent; index 0 is the baseline).
            ds.spiHistory[period] = ds.spi;
            ds.cpiHistory[period] = ds.cpi;

            // Normalize result and persist a clamped 0-100 score every period (Grading Contract C1).
            result.spi = ds.spi;
            result.cpi = ds.cpi;
            result.projectedCost = Math.round(ds.projectedCost);
            result.projectedMonths = ds.projectedMonths;
            result.stakeholderConfidence = ds.stakeholderConfidence;
            result.rootCauseAccuracy = ds.rootCauseAccuracy;
            result.recoveryBudgetUsed = ds.recoveryBudgetUsed;
            var overall = this._composite(ds);
            ds.performance = { overallScore: overall, grade: this._letter(overall) };
            ds.performanceTier = this._perfKey(overall);
            result.overallScore = overall;
            result.score = overall;

            // Render the briefing for the round the framework has advanced to (was +1 -> skipped a round).
            var self = this;
            setTimeout(function() {
                self._updateBriefing(state);
            }, 400);

            return result;
        }

        _composite(ds) {
            var score = 0;
            var spi = ds.spi, cpi = ds.cpi, months = ds.projectedMonths, conf = ds.stakeholderConfidence;
            if (spi >= 0.98) score += 25; else if (spi >= 0.93) score += 18; else if (spi >= 0.88) score += 10;
            if (cpi >= 0.95) score += 25; else if (cpi >= 0.90) score += 18; else if (cpi >= 0.85) score += 10;
            if (months <= 50) score += 25; else if (months <= 53) score += 18; else if (months <= 56) score += 10;
            if (conf >= 75) score += 25; else if (conf >= 60) score += 18; else if (conf >= 45) score += 10;
            return score < 0 ? 0 : (score > 100 ? 100 : score);
        }

        _letter(score) {
            if (score >= 90) return 'A';
            if (score >= 75) return 'B';
            if (score >= 60) return 'C';
            if (score >= 40) return 'D';
            return 'F';
        }

        _perfKey(score) {
            if (score >= 85) return 'excellent';
            if (score >= 65) return 'good';
            if (score >= 45) return 'acceptable';
            return 'needs_improvement';
        }

