        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var finalSpi = r.spi != null ? r.spi : 0.85;
            var finalCpi = r.cpi != null ? r.cpi : 0.88;
            var finalMonths = r.projectedMonths != null ? r.projectedMonths : 57;
            var finalCost = r.projectedCost != null ? r.projectedCost : 1380;
            var finalConf = r.stakeholderConfidence != null ? r.stakeholderConfidence : 50;
            var budget = r.recoveryBudgetUsed != null ? r.recoveryBudgetUsed : 0;
            var rca = r.rootCauseAccuracy != null ? r.rootCauseAccuracy : 0;
            var score = r.overallScore != null ? r.overallScore : this._composite({ spi: finalSpi, cpi: finalCpi, projectedMonths: finalMonths, stakeholderConfidence: finalConf });
            var perfKey = this._perfKey(score);
            var t = function(k) { return window.mySimulation ? window.mySimulation.t(k) : k; };

            var insights = [];
            insights.push(finalSpi >= 0.95 ? t('insight_spi_good') : t('insight_spi_bad'));
            insights.push(finalCpi >= 0.92 ? t('insight_cpi_good') : t('insight_cpi_bad'));
            insights.push(finalConf >= 70 ? t('insight_conf_good') : t('insight_conf_bad'));
            insights.push(rca >= 70 ? t('insight_rca_good') : t('insight_rca_bad'));

            return {
                finalSPI: finalSpi,
                finalCPI: finalCpi,
                projectedMonths: finalMonths,
                projectedCost: finalCost,
                stakeholderConfidence: finalConf,
                recoveryBudget: budget,
                score: score,
                overallScore: score,
                composite: score,
                grade: this._letter(score),
                performance: perfKey,
                performanceLabel: t('perf_' + perfKey),
                insights: insights
            };
        }

