        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (state.currentPeriod === 1 && ds.rootCauseAccuracy < 50) {
                return window.mySimulation.t('hint_poor_analysis');
            }
            if (state.currentPeriod === 1 && ds.rootCauseAccuracy >= 70) {
                return window.mySimulation.t('hint_good_analysis');
            }
            if (ds.spi > 0.93 && ds.cpi > 0.90) {
                return window.mySimulation.t('hint_spi_improving');
            }
            if (ds.projectedCost > 1400) {
                return window.mySimulation.t('hint_over_budget');
            }
            if (ds.stakeholderConfidence < 40) {
                return window.mySimulation.t('hint_confidence_low');
            }
            return null;
        }

